import { app, BrowserWindow, ipcMain, shell, Tray, Menu, nativeImage } from 'electron';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import Store from 'electron-store';
import { exec } from 'node:child_process';
import { promisify } from 'node:util';

const execAsync = promisify(exec);
const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Set application name for macOS
if (process.platform === 'darwin') {
  app.name = 'LocalHub';
}

const store = new Store();

let mainWindow: BrowserWindow | null = null;
let tray: Tray | null = null;
let isQuitting = false;
const APP_ICON_FILE = 'localhub.png';
const APP_ICON_BASE64 = 'data:image/png;base64,';
const SHOW_IN_MENU_BAR_KEY = 'showInMenuBar';

function getAppIcon() {
  const appIconPath = path.join(process.env.VITE_PUBLIC || '', APP_ICON_FILE);
  let appIcon = nativeImage.createFromPath(appIconPath);
  if (appIcon.isEmpty()) appIcon = nativeImage.createFromDataURL(`data:image/png;base64,${APP_ICON_BASE64}`);
  return appIcon.resize({ width: 64, height: 64 });
}

function getTrayIcon() {
  const trayPath = path.join(process.env.VITE_PUBLIC || '', 'trayTemplate.png');
  let trayIcon = nativeImage.createFromPath(trayPath);
  if (trayIcon.isEmpty()) {
    const backupPath = path.join(process.env.VITE_PUBLIC || '', 'localhub.png');
    trayIcon = nativeImage.createFromPath(backupPath);
  }
  if (trayIcon.isEmpty()) trayIcon = nativeImage.createFromDataURL(`data:image/png;base64,${APP_ICON_BASE64}`);

  trayIcon = trayIcon.resize({ width: 18, height: 18 });

  if (process.platform === 'darwin') {
    // macOS menu bar uses template image for reliable light/dark rendering.
    trayIcon.setTemplateImage(true);
  }

  return trayIcon;
}

function isShowInMenuBarEnabled() {
  const value = store.get(SHOW_IN_MENU_BAR_KEY);
  return value === undefined ? true : Boolean(value);
}

function setShowInMenuBarEnabled(enabled: boolean) {
  store.set(SHOW_IN_MENU_BAR_KEY, enabled);
}

process.env.APP_ROOT = path.join(__dirname, '..');
export const VITE_DEV_SERVER_URL = process.env['VITE_DEV_SERVER_URL'];
export const MAIN_DIST = path.join(process.env.APP_ROOT, 'dist-electron');
export const RENDERER_DIST = path.join(process.env.APP_ROOT, 'dist');

process.env.VITE_PUBLIC = VITE_DEV_SERVER_URL ? path.join(process.env.APP_ROOT, 'public') : RENDERER_DIST;

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 900,
    height: 700,
    minWidth: 800,
    minHeight: 600,
    title: 'LocalHub',
    icon: getTrayIcon(),
    webPreferences: {
      preload: path.join(__dirname, 'preload.mjs'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  if (VITE_DEV_SERVER_URL) {
    mainWindow.loadURL(VITE_DEV_SERVER_URL);
  } else {
    // FIX: Using path.join with file:// protocol or just a cleaner path mapping
    // Ensure index.html is loaded correctly in the production bundle
    mainWindow.loadFile(path.join(RENDERER_DIST, 'index.html'));
  }

  // Open external links in default browser
  mainWindow.webContents.setWindowOpenHandler((details) => {
    shell.openExternal(details.url);
    return { action: 'deny' };
  });

  // Hide the window instead of closing it
  mainWindow.on('close', (event) => {
    if (!isQuitting && tray) {
      event.preventDefault();
      mainWindow?.hide();
      // On macOS, it's also common to hide the dock icon if the window is hidden, 
      // but keeping it is fine as we have a tray.
    }
  });
}

// Port scanner logic
async function scanPorts() {
  const platform = process.platform;
  const servicesMap = new Map<number, any>();

  try {
    if (platform === 'win32') {
      // Windows implementation using netstat and tasklist
      const { stdout: netstatOut } = await execAsync('netstat -ano | findstr LISTENING');
      const netstatLines = netstatOut.split('\n').filter(line => line.trim());
      
      // Get all process mapping at once to avoid multiple tasklist calls
      const tasklistMap = new Map<number, string>();
      try {
        const { stdout: tasklistOut } = await execAsync('tasklist /fo csv /nh');
        const tasklistLines = tasklistOut.split('\n').filter(line => line.trim());
        tasklistLines.forEach(line => {
          // Format: "System Idle Process","4","Services","0","8 K"
          const parts = line.split('","');
          if (parts.length >= 2) {
            const processName = parts[0].replace(/^"/, '');
            const pid = parseInt(parts[1], 10);
            tasklistMap.set(pid, processName);
          }
        });
      } catch (err) {
        console.error('Failed to get tasklist on Windows:', err);
      }

      for (const line of netstatLines) {
        // TCP    0.0.0.0:135      0.0.0.0:0      LISTENING       1164
        const parts = line.trim().split(/\s+/);
        if (parts.length >= 5) {
          const localAddress = parts[1];
          const portMatch = localAddress.match(/:(\d+)$/);
          const port = portMatch ? parseInt(portMatch[1], 10) : null;
          const pid = parseInt(parts[4], 10);

          if (port) {
            const processName = tasklistMap.get(pid) || 'Unknown';
            servicesMap.set(port, {
              id: `${pid}-${port}`,
              port,
              process: processName,
              pid,
              type: 'http',
              status: 'online',
              isManual: false
            });
          }
        }
      }
    } else {
      // macOS/Linux implementation using lsof
      const { stdout } = await execAsync('lsof -i -P -n | grep LISTEN');
      const lines = stdout.split('\n').filter(line => line.trim());
      
      for (const line of lines) {
        const parts = line.split(/\s+/);
        const processName = parts[0];
        const pid = parseInt(parts[1], 10);
        const namePart = parts[parts.length - 2]; 
        const portMatch = namePart.match(/:(\d+)$/);
        const port = portMatch ? parseInt(portMatch[1], 10) : null;
        
        if (port) {
          servicesMap.set(port, {
            id: `${pid}-${port}`,
            port,
            process: processName,
            pid,
            type: 'http', 
            status: 'online',
            isManual: false
          });
        }
      }
    }
    
    return Array.from(servicesMap.values());
  } catch (error) {
    console.error('Port scan failed:', error);
    return [];
  }
}

function updateTrayMenu() {
  if (!tray) return;

  const pinnedPorts = (store.get('pinnedPorts') as number[]) || [];
  const services = (store.get('services') as any[]) || [];

  const template: Electron.MenuItemConstructorOptions[] = [
    {
      label: 'Open LocalHub',
      click: () => {
        if (mainWindow) {
          mainWindow.show();
          mainWindow.focus();
        } else {
          createWindow();
        }
      }
    },
    { type: 'separator' }
  ];

  if (pinnedPorts.length > 0) {
    template.push({ label: '📌 Pinned Services', enabled: false });
    
    for (const port of pinnedPorts) {
      const service = services.find(s => s.port === port);
      const alias = service?.alias || service?.process || `Port ${port}`;
      const pathStr = service?.path ? (service.path.startsWith('/') ? service.path : `/${service.path}`) : '';
      const scheme = service?.type === 'https' ? 'https' : 'http';
      const url = `${scheme}://localhost:${port}${pathStr}`;
      
      template.push({
        label: `  ${alias} (:${port})`,
        click: () => {
          shell.openExternal(url);
        }
      });
    }
    template.push({ type: 'separator' });
  }

  template.push({
    label: 'Quit',
    click: () => {
      isQuitting = true;
      app.quit();
    }
  });

  const contextMenu = Menu.buildFromTemplate(template);
  
  if (process.platform === 'win32') {
    // On Windows, setting the context menu directly overrides the click event.
    // So we don't set it, we just attach it to the tray object for manual popup.
    (tray as any)._contextMenu = contextMenu;
  } else {
    // On macOS, setting it ensures native behavior and right-click works fine.
    // However, setContextMenu disables the 'click' event on macOS. 
    // To allow BOTH left-click (open app) and right-click (open menu), we MUST NOT use setContextMenu on macOS either.
    (tray as any)._contextMenu = contextMenu;
  }
}

function createTray() {
  const trayIcon = getTrayIcon();
  tray = new Tray(trayIcon);
  tray.setToolTip('LocalHub');
  tray.setImage(trayIcon);

  // Fallback: ensure there is always a visible item even if icon theme rendering fails.
  if (process.platform === 'darwin') {
    tray.setTitle(trayIcon.isEmpty() ? 'LH' : '');
  }

  // Left click: Open main window
  tray.on('click', () => {
    if (mainWindow) {
      if (mainWindow.isVisible()) {
        mainWindow.focus();
      } else {
        mainWindow.show();
      }
    } else {
      createWindow();
    }
  });

  // Right click: Show context menu
  tray.on('right-click', () => {
    const menu = (tray as any)._contextMenu;
    if (menu) {
      tray?.popUpContextMenu(menu);
    }
  });

  updateTrayMenu();
}

function syncTrayVisibility() {
  const shouldShow = isShowInMenuBarEnabled();
  if (shouldShow && !tray) createTray();
  if (!shouldShow && tray) {
    tray.destroy();
    tray = null;
  }
}

function createAppMenu() {
  if (process.platform !== 'darwin') return;

  const menu = Menu.buildFromTemplate([
    {
      label: app.name,
      submenu: [
        { role: 'about' },
        { type: 'separator' },
        {
          label: '是否在菜单栏显示',
          type: 'checkbox',
          checked: isShowInMenuBarEnabled(),
          click: (item) => {
            setShowInMenuBarEnabled(Boolean(item.checked));
            syncTrayVisibility();
            createAppMenu();
          },
        },
        {
          label: '显示控制面板',
          click: () => {
            if (mainWindow) {
              mainWindow.show();
              mainWindow.focus();
            } else {
              createWindow();
            }
          },
        },
        { type: 'separator' },
        { role: 'quit' },
      ],
    },
  ]);

  Menu.setApplicationMenu(menu);
}

app.whenReady().then(() => {
  if (process.platform === 'darwin' && app.dock) {
    app.dock.setIcon(getAppIcon());
  }

  createWindow();
  syncTrayVisibility();
  createAppMenu();

  store.onDidChange('pinnedPorts', () => {
    updateTrayMenu();
  });
  store.onDidChange('services', () => {
    updateTrayMenu();
  });

  ipcMain.handle('scan-ports', async () => {
    return await scanPorts();
  });

  ipcMain.handle('get-store', (event, key) => {
    return store.get(key);
  });

  ipcMain.handle('set-store', (event, key, value) => {
    store.set(key, value);
    return true;
  });

  ipcMain.handle('delete-store', (event, key) => {
    store.delete(key);
    return true;
  });

  ipcMain.handle('open-url', (event, url) => {
    shell.openExternal(url);
  });

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('before-quit', () => {
  isQuitting = true;
});

app.on('window-all-closed', () => {
  // If the tray icon is active, do not quit on window close, keep it in background
  if (process.platform !== 'darwin' && !tray) {
    app.quit();
  }
});
